<script setup>
import { computed, onMounted, reactive, ref, watch } from 'vue';
import MEmptyState from '../../components/mds/MEmptyState.vue'; import MMobileTopBar from '../../components/mds/MMobileTopBar.vue'; import MSpinner from '../../components/mds/MSpinner.vue';
import { HostSurface } from '../../platform/host-adapter.mjs'; import { createEventsApi } from './domain/events-api.mjs'; import { eventDetailViewModel } from './domain/event-detail.mjs';
import EventsListDesktop from './desktop/EventsListDesktop.vue'; import EventsListMobile from './mobile/EventsListMobile.vue'; import EventCreateDesktop from './desktop/EventCreateDesktop.vue'; import EventCreateMobile from './mobile/EventCreateMobile.vue'; import EventDetailDesktop from './desktop/EventDetailDesktop.vue'; import EventDetailMobile from './mobile/EventDetailMobile.vue';
import EventCostFormDesktop from './desktop/EventCostFormDesktop.vue'; import EventCostFormMobile from './mobile/EventCostFormMobile.vue';
const props = defineProps({ eventId: { type: Number, default: null }, surface: String, adapter: Object, hostUnavailable: Boolean }); const emit = defineEmits(['back']); const api = createEventsApi(); const safeArea = ref(props.adapter?.getSafeArea?.() || {}); const isNative = computed(() => props.surface === HostSurface.NATIVE); const state = reactive({ phase:'loading',rows:[],total:0,page:1,pageSize:20,search:'',record:null,detail:null,permissions:null,mode:'read',saving:false,saveError:'',deleting:false,deleteError:'',uploading:false,fileError:'',costSaving:false,costDeleting:false,costError:'',costRecord:null,costCategory:'sponsor',suppliers:[],error:null }); const canCreate = computed(()=>state.permissions?.modules?.events?.includes('create')===true); const canEdit = computed(()=>state.permissions?.modules?.events?.includes('edit')===true); const canDelete = computed(()=>state.permissions?.modules?.events?.includes('delete')===true); const canManageCosts = computed(()=>canEdit.value && !state.detail?.costGroups?.some((group)=>group.items.some((item)=>item.amountMasked))); const safeAreaStyle = computed(()=>Object.fromEntries(['top','right','bottom','left'].flatMap((side)=>Number.isFinite(Number(safeArea.value?.[side]))?[[`--mds-mobile-safe-${side}`,`${Number(safeArea.value[side])}px`]]:[])));
async function load({page=state.page,search=state.search}={}) { if(props.hostUnavailable){state.phase='error';state.error={status:503,message:'Native host chưa sẵn sàng. Ứng dụng không chuyển sang giao diện desktop thay thế.'};return;} state.phase='loading'; state.error=null; try { const sessionPromise=api.getCurrentUser(); if(props.eventId){const [payload,session]=await Promise.all([api.get(props.eventId),sessionPromise]); Object.assign(state,{record:payload.record,detail:eventDetailViewModel(payload),permissions:session?.permissions||null,mode:'detail',phase:'ready'}); return;} const [p,session]=await Promise.all([api.getList({page,pageSize:state.pageSize,search}),sessionPromise]); Object.assign(state,{rows:p.rows,total:p.total,page:p.page,pageSize:p.pageSize,search,record:null,detail:null,permissions:session?.permissions||null,mode:'read',phase:'ready'}); } catch(error){state.phase='error';state.error=error;} }
function beginCreate(){if(canCreate.value){state.mode='create';state.saveError='';}} function beginEdit(){if(canEdit.value&&props.eventId){state.mode='edit';state.saveError='';}} function openEvent(id){location.hash=`events/${Number(id)}`;} function showList(){location.hash='events';} async function save(input){state.saving=true;try{const saved=await api.save(input, props.eventId); if(props.eventId) await load(); else location.hash=`events/${saved.id}`;}catch(error){state.saveError=error.message;}finally{state.saving=false;}} async function deleteEvent(){if(!canDelete.value||!props.eventId)return; state.deleting=true;state.deleteError='';try{await api.delete(props.eventId);showList();}catch(error){state.deleteError=error.message;}finally{state.deleting=false;}} async function uploadFiles({kind,files}){if(!canEdit.value||!props.eventId||!Array.isArray(files)||files.length===0)return; state.uploading=true;state.fileError='';try{await api.uploadFiles(props.eventId,files,{kind});await load();}catch(error){state.fileError=error.message;}finally{state.uploading=false;}} async function beginCost(payload){if(!canManageCosts.value||!props.eventId)return; const item=payload?.item||null; state.costCategory=item?.category||payload?.category||'sponsor'; state.costRecord=item; state.costError=''; state.mode='cost'; if(state.costCategory==='organization'){try{state.suppliers=await api.listSuppliers();}catch(error){state.costError=error.message;}}} async function saveCost(input){if(!canManageCosts.value||!props.eventId)return; state.costSaving=true;state.costError='';try{await api.saveCost(props.eventId,input,state.costRecord?.id);await load();}catch(error){state.costError=error.message;}finally{state.costSaving=false;}} async function deleteCost(item){if(!canDelete.value||!props.eventId||!item?.id)return; state.costDeleting=true;state.costError='';try{await api.deleteCost(props.eventId,item.id);await load();}catch(error){state.costError=error.message;}finally{state.costDeleting=false;}} async function back(){if(isNative.value&&props.adapter)return props.adapter.goBack({reason:'events-list'});emit('back');} watch(()=>props.eventId,()=>load()); onMounted(load);
</script>
<template><div v-if="state.phase==='loading'" :class="isNative?'mds-mobile-app grid h-[100dvh] place-items-center bg-[var(--mds-bg)]':'grid min-h-[360px] place-items-center bg-[var(--mds-bg-page)]'"><MSpinner :size="28"/></div><section v-else-if="state.phase==='error'" :class="isNative?'mds-mobile-app min-h-[100dvh] bg-[var(--mds-bg)]':'min-h-[360px] bg-[var(--mds-bg-page)]'"><MMobileTopBar v-if="isNative" title="Sự kiện" @back="back"/><MEmptyState :title="state.error.status===404?'Không tìm thấy sự kiện':state.error.status===403?'Bạn không có quyền xem sự kiện':'Không thể mở sự kiện'" :description="state.error.message"/></section><EventCostFormMobile v-else-if="isNative&&state.mode==='cost'" :record="state.costRecord" :category="state.costCategory" :editing="Boolean(state.costRecord)" :saving="state.costSaving" :error="state.costError" :suppliers="state.suppliers" :safe-area-style="safeAreaStyle" @cancel="state.mode='detail'" @save="saveCost"/><EventDetailMobile v-else-if="isNative&&state.mode==='detail'" :detail="state.detail" :can-edit="canEdit" :can-delete="canDelete" :can-manage-costs="canManageCosts" :cost-deleting="state.costDeleting" :cost-error="state.costError" :delete-working="state.deleting" :delete-error="state.deleteError" :uploading="state.uploading" :file-error="state.fileError" :safe-area-style="safeAreaStyle" @back="showList" @edit="beginEdit" @delete="deleteEvent" @upload="uploadFiles" @add-cost="beginCost({category:$event})" @edit-cost="beginCost({item:$event})" @delete-cost="deleteCost"/><EventCreateMobile v-else-if="isNative&&(state.mode==='create'||state.mode==='edit')" :record="state.record" :editing="state.mode==='edit'" :saving="state.saving" :error="state.saveError" :safe-area-style="safeAreaStyle" @cancel="state.mode=props.eventId?'detail':'read'" @save="save"/><EventsListMobile v-else-if="isNative" :rows="state.rows" :total="state.total" :page="state.page" :page-size="state.pageSize" :search="state.search" :can-create="canCreate" :safe-area-style="safeAreaStyle" @back="back" @create="beginCreate" @open="openEvent" @search="load({page:1,search:$event})" @page="load({page:$event})"/><EventCostFormDesktop v-else-if="state.mode==='cost'" :record="state.costRecord" :category="state.costCategory" :editing="Boolean(state.costRecord)" :saving="state.costSaving" :error="state.costError" :suppliers="state.suppliers" @cancel="state.mode='detail'" @save="saveCost"/><EventDetailDesktop v-else-if="state.mode==='detail'" :detail="state.detail" :can-edit="canEdit" :can-delete="canDelete" :can-manage-costs="canManageCosts" :cost-deleting="state.costDeleting" :cost-error="state.costError" :delete-working="state.deleting" :delete-error="state.deleteError" :uploading="state.uploading" :file-error="state.fileError" @back="showList" @edit="beginEdit" @delete="deleteEvent" @upload="uploadFiles" @add-cost="beginCost({category:$event})" @edit-cost="beginCost({item:$event})" @delete-cost="deleteCost"/><EventCreateDesktop v-else-if="state.mode==='create'||state.mode==='edit'" :record="state.record" :editing="state.mode==='edit'" :saving="state.saving" :error="state.saveError" @cancel="state.mode=props.eventId?'detail':'read'" @save="save"/><EventsListDesktop v-else :rows="state.rows" :total="state.total" :page="state.page" :page-size="state.pageSize" :search="state.search" :can-create="canCreate" @create="beginCreate" @open="openEvent" @search="load({page:1,search:$event})" @page="load({page:$event})"/></template>
